-- Momentum sector caps group by GICS sector (momSector in lib/momentum/sector-key.ts) instead of the
-- 2-digit SIC code. The build stores the sector each snapshot row was capped under; sic2 stays for reference.
alter table public.ss_mom_snapshots add column if not exists sector text;

-- Screener: recompute every non-S&P sector from its SIC code with the corrected mapping
-- (3826 lab instruments, 5047/5122 medical & drug wholesale and 8731 research are now Health Care,
-- and codes the old mapping left blank are filled). S&P 500 names keep their GICS sector.
-- Generated from lib/sectors.ts sectorFromSic for every SIC code on a non-S&P ticker.
update public.ss_tickers t set sector = m.sector
